{
  "segment_function": "To analyze the public realm of homo faber (the exchange market), contrast modern exclusion of political man with ancient exclusions, and examine the necessity of isolation for craftsmanship.",
  "claims": [
    {
      "claim": "The modern age aimed to exclude political man (who acts and speaks) from its public realm, much as antiquity sought to exclude homo faber.",
      "claim_type": "author_position",
      "supporting_excerpt": "The truth of this remark lies in the fact that the modern age was as intent on excluding political man, that is, man who acts and speaks, from its public realm as antiquity was on excluding homo faber.",
      "support_kind": "direct",
      "qualifications": [
        "In both instances the exclusion was not a matter of course"
      ],
      "confidence": 1.0
    },
    {
      "claim": "Homo faber forms a public realm of his own through the exchange market, driven by the need to show hand-made products and receive esteem.",
      "claim_type": "author_position",
      "supporting_excerpt": "His public realm is the exchange market, where he can show the products of his hand and receive the esteem which is due him.",
      "support_kind": "direct",
      "qualifications": [
        "even though it may not be a political realm, properly speaking"
      ],
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "Homo faber",
      "definition": "The builder of the world and producer of things whose products are produced in isolation."
    }
  ],
  "distinctions": [
    {
      "item_a": "Animal laborans",
      "item_b": "Homo faber",
      "distinction": "Animal laborans has a worldless, herdlike social life and cannot build a public worldly realm, whereas homo faber is fully capable of having a public realm of his own (the exchange market)."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The modern age based its view of society on the productivity of homo faber.",
    "Isolation is a necessary condition for craftsmanship and mastership.",
    "Conspicuous production is a trait of a society of producers."
  ]
}

